import{_ as o,C as i,o as a,c as s,ao as e,E as d}from"./chunks/framework.D7TN4pt9.js";const u=JSON.parse('{"title":"Color Coding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/color-coding.md","filePath":"guide/color-coding.md","lastUpdated":null}'),r={name:"guide/color-coding.md"};function l(h,t,c,g,y,p){const n=i("DemoShot");return a(),s("div",null,[t[0]||(t[0]=e('<h1 id="Color-Coding" tabindex="-1">Color Coding <a class="header-anchor" href="#Color-Coding" aria-label="Permalink to &quot;Color Coding {#Color-Coding}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Status: partly built</p><p>What renders today is the per-session <strong>agent work-state</strong> color (idle · working · blocked · waiting · done, on the Sessions strip and nav rows) and the <strong>stale-annotation</strong> drift badge, which is per file (the file&#39;s content hash against the annotation&#39;s <code>synced_against</code>) and shows on the selected file row in Files mode. The per-entity provenance states in the table below (user-edited, agent-edited accept/reject, immutable/external, favorited) are planned; a pinned file already renders, as a bright cyan row in the navigation tree rather than an accented border.</p></div><p>Color coding is a cross-cutting layer. The same entity carries the same provenance no matter which mode you view it in, so Ship of Tools renders that provenance <strong>uniformly across all modes</strong> — in the design, a stale annotation looks stale in every mode, because staleness belongs to the entity, not to the view. Built today, staleness is a property of a <em>file</em> and shows on that file&#39;s row in Files mode.</p><p>Color and badging are orthogonal to mode. A mode decides <em>what tree to show</em>; the color layer decides <em>how each node is tinted</em> based on who touched it, when, and whether its annotation still matches the code.</p>',4)),d(n,{name:"state-colors",caption:"Session rows in their work-state colors, each with the reason it last reported."}),t[1]||(t[1]=e('<h2 id="The-states" tabindex="-1">The states <a class="header-anchor" href="#The-states" aria-label="Permalink to &quot;The states {#The-states}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">State</th><th style="text-align:right;">Appearance</th><th style="text-align:right;">Meaning</th><th style="text-align:right;">Built today</th></tr></thead><tbody><tr><td style="text-align:right;">User-edited recently</td><td style="text-align:right;">Warm color, fades over time</td><td style="text-align:right;">You touched this entity lately; the warmth decays as it ages.</td><td style="text-align:right;">No</td></tr><tr><td style="text-align:right;">Agent-edited, unaccepted</td><td style="text-align:right;">Distinct color (unresolved diff)</td><td style="text-align:right;">An agent changed this and you have not yet accepted or discarded the change.</td><td style="text-align:right;">No</td></tr><tr><td style="text-align:right;">Agent-edited, accepted</td><td style="text-align:right;">Neutral, small sigil</td><td style="text-align:right;">An agent&#39;s change that you accepted; marked with a small sigil but otherwise neutral.</td><td style="text-align:right;">No</td></tr><tr><td style="text-align:right;">Immutable / external</td><td style="text-align:right;">Dimmed</td><td style="text-align:right;">Base, dependencies, vendored code — not yours to edit, rendered dimmed.</td><td style="text-align:right;">No</td></tr><tr><td style="text-align:right;">Stale annotation</td><td style="text-align:right;">Yellowed</td><td style="text-align:right;">The entity&#39;s <a href="./concept-layer">concept annotation</a> was written against an older version of its file (the file&#39;s content hash differs from <code>synced_against</code>).</td><td style="text-align:right;">Yes, per file, on the selected row in Files mode; per-entity staleness is not built</td></tr><tr><td style="text-align:right;">Pinned file</td><td style="text-align:right;">Bright cyan, bold row</td><td style="text-align:right;">You pinned this file to keep its preview while browsing.</td><td style="text-align:right;">Yes, in the navigation tree; no other entity can be pinned or favorited</td></tr><tr><td style="text-align:right;">Agent work state</td><td style="text-align:right;">Working green, blocked red, waiting purple, done blue, idle gray</td><td style="text-align:right;">A session&#39;s work state; see <a href="./../concepts/work-state">Work-state colors</a>.</td><td style="text-align:right;">Yes, on Sessions rows and the session strip</td></tr></tbody></table><h2 id="Why-it-is-mode-independent" tabindex="-1">Why it is mode-independent <a class="header-anchor" href="#Why-it-is-mode-independent" aria-label="Permalink to &quot;Why it is mode-independent {#Why-it-is-mode-independent}&quot;">​</a></h2><p>Provenance is a fact about an entity: who edited it, when, whether its annotation is current. None of those facts change when you switch the root tree from Files to Modules. Encoding them once, at the entity level, means you do not relearn a color scheme per mode — in Files mode a yellowed badge means &quot;the prose may not match the code.&quot; (A Sessions row is also drawn yellow when its capsule is held by a different build.)</p><p>The &quot;stale annotation&quot; state is the direct rendering of the staleness detection described in <a href="./concept-layer">The Concept Layer</a>: when an annotation&#39;s <code>synced_against</code> hash no longer matches the current content hash of its file, the file&#39;s row yellows until you refresh it. In the design the same yellow follows the entity into every mode; today it is drawn for the selected file row in Files mode only.</p>',5))])}const w=o(r,[["render",l]]);export{u as __pageData,w as default};
